Function precioFinal <- ConDescuento(precio As Integer, porcentaje As Integer)
  Define precioFinal As Integer;
  precioFinal <- precio * (100 - porcentaje) Div 100;
EndFunction

Algorithm Kiosco
  Define porcentaje, precio As Integer;
  Define total As Integer <- 0;
  Write "¿Qué descuento?";
  Read porcentaje;
  For i <- 1 To 3 Do
    Read precio;
    total <- total + ConDescuento(precio, porcentaje);
  EndFor
  Write "Total: ", total;
EndAlgorithm

Function precioFinal <- ConDescuento(precio As Integer, porcentaje As Integer)
  Define precioFinal As Integer;
  precioFinal <- precio * (100 - porcentaje) Div 100;
EndFunction

Algorithm Pruebas
  Write ConDescuento(100, 10);
  Write ConDescuento(100, 0);
  Write ConDescuento(100, 100);
  Write ConDescuento(15, 10);
EndAlgorithm
